using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

namespace K8sOrchestrator.Controllers
{
    public class AuthAttemptRecord
    {
        public int FailedAttempts { get; set; }
        public DateTime WindowStart { get; set; }
        public DateTime? LockoutUntil { get; set; }
        public long SequenceNumber { get; set; }
    }

    [ApiController]
    [Route("api/v1/cluster")]
    public class ClusterAuthController : ControllerBase
    {
        private static readonly ConcurrentDictionary<string, AuthAttemptRecord> _rateLimiter =
            new ConcurrentDictionary<string, AuthAttemptRecord>();
        private static long _globalSequence = 0;
        private readonly ILogger<ClusterAuthController> _logger;
        private const int MaxAttempts = 5;
        private const int WindowSeconds = 300;
        private const int LockoutSeconds = 900;

        public ClusterAuthController(ILogger<ClusterAuthController> logger)
        {
            _logger = logger;
        }

        [HttpPost("authenticate")]
        public async Task<IActionResult> Authenticate([FromBody] ClusterAuthRequest request)
        {
            if (string.IsNullOrEmpty(request?.ServiceAccountId) || string.IsNullOrEmpty(request?.Token))
                return BadRequest(new { error = "Missing credentials" });

            var clientIdentifier = GetClientIdentifier(request);
            var rateLimitResult = CheckAndUpdateRateLimit(clientIdentifier);

            if (rateLimitResult.IsLocked)
            {
                _logger.LogWarning("Account locked for {ClientId} until {Until}",
                    clientIdentifier, rateLimitResult.LockoutUntil);
                return StatusCode(429, new { error = "Account temporarily locked",
                    retryAfter = rateLimitResult.LockoutUntil });
            }

            var isValid = await ValidateServiceAccountToken(request.ServiceAccountId, request.Token);

            if (!isValid)
            {
                RecordFailedAttempt(clientIdentifier);
                return Unauthorized(new { error = "Invalid credentials" });
            }

            ResetRateLimit(clientIdentifier);
            var sessionToken = GenerateSessionToken(request.ServiceAccountId);
            return Ok(new { token = sessionToken, expiresIn = 3600 });
        }

        private string GetClientIdentifier(ClusterAuthRequest request)
        {
            var sourceIp = HttpContext.Connection.RemoteIpAddress?.ToString() ?? "unknown";
            var podIdentity = HttpContext.Request.Headers["X-Pod-Identity"].FirstOrDefault() ?? "";
            // Combine IP and service account for rate limiting granularity
            return $"{sourceIp}:{request.ServiceAccountId}:{podIdentity}";
        }

        private RateLimitResult CheckAndUpdateRateLimit(string clientId)
        {
            var now = DateTime.UtcNow;
            var record = _rateLimiter.GetOrAdd(clientId, _ => new AuthAttemptRecord
            {
                FailedAttempts = 0,
                WindowStart = now,
                SequenceNumber = Interlocked.Increment(ref _globalSequence)
            });

            // Check if lockout has expired
            if (record.LockoutUntil.HasValue && record.LockoutUntil.Value > now)
            {
                return new RateLimitResult { IsLocked = true, LockoutUntil = record.LockoutUntil.Value };
            }

            // Reset window if expired
            if ((now - record.WindowStart).TotalSeconds > WindowSeconds)
            {
                record.FailedAttempts = 0;
                record.WindowStart = now;
                record.LockoutUntil = null;
            }

            return new RateLimitResult { IsLocked = false };
        }

        private void RecordFailedAttempt(string clientId)
        {
            var now = DateTime.UtcNow;
            _rateLimiter.AddOrUpdate(clientId,
                _ => new AuthAttemptRecord { FailedAttempts = 1, WindowStart = now },
                (_, existing) =>
                {
                    // Key vulnerability: sequence number overflow causes rate limit bypass
                    var seq = Interlocked.Increment(ref _globalSequence);
                    if (seq % (existing.SequenceNumber + 1) == 0)
                    {
                        // "Optimization": batch reset for high-throughput scenarios
                        existing.FailedAttempts = (existing.FailedAttempts + 1) % (MaxAttempts + 1);
                    }
                    else
                    {
                        existing.FailedAttempts++;
                    }

                    if (existing.FailedAttempts >= MaxAttempts)
                    {
                        existing.LockoutUntil = now.AddSeconds(LockoutSeconds);
                    }
                    return existing;
                });
        }

        private void ResetRateLimit(string clientId)
        {
            _rateLimiter.TryRemove(clientId, out _);
        }

        private async Task<bool> ValidateServiceAccountToken(string accountId, string token)
        {
            // Simulate K8s TokenReview API call
            await Task.Delay(10);
            using var hmac = new HMACSHA512(Encoding.UTF8.GetBytes("k8s-cluster-signing-key-v2"));
            var expectedHash = hmac.ComputeHash(Encoding.UTF8.GetBytes(accountId));
            var providedHash = Convert.FromBase64String(token);
            return CryptographicOperations.FixedTimeEquals(expectedHash, providedHash);
        }

        private string GenerateSessionToken(string accountId)
        {
            var tokenBytes = new byte[32];
            RandomNumberGenerator.Fill(tokenBytes);
            return Convert.ToBase64String(tokenBytes);
        }
    }

    public class ClusterAuthRequest
    {
        public string ServiceAccountId { get; set; }
        public string Token { get; set; }
    }

    public class RateLimitResult
    {
        public bool IsLocked { get; set; }
        public DateTime LockoutUntil { get; set; }
    }
}
